1|/* check that utf8proc_normalize_utf32 passes uninterpretable codepoints through
2|   rather than deleting them, and never composes across one */
3|static void check_normalize_utf32(const char *name,
4|                                  const utf8proc_int32_t *input, utf8proc_ssize_t len,
5|                                  const utf8proc_int32_t *expected, utf8proc_ssize_t expected_len)
6|{
7|    utf8proc_int32_t buffer[8];
8|    utf8proc_ssize_t i, result;
9|
10|    check(len <= (utf8proc_ssize_t) (sizeof(buffer)/sizeof(*buffer)), "%s: test buffer too small", name);
11|    for (i = 0; i < len; ++i) buffer[i] = input[i];
12|    result = utf8proc_normalize_utf32(buffer, len, UTF8PROC_COMPOSE);
13|    check(result == expected_len, "%s: returned length %zd, expected %zd", name, result, expected_len);
14|    for (i = 0; i < expected_len; ++i)
15|        check(buffer[i] == expected[i], "%s: buffer[%zd] = 0x%x, expected 0x%x",
16|              name, i, buffer[i], expected[i]);
17|}
