617|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_normalize_utf32(utf8proc_int32_t *buffer, utf8proc_ssize_t length, unsigned int options) {
618|  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored */
619|  if (options & (UTF8PROC_NLF2LS | UTF8PROC_NLF2PS | UTF8PROC_STRIPCC)) {
620|    utf8proc_ssize_t rpos;
621|    utf8proc_ssize_t wpos = 0;
622|    utf8proc_int32_t uc;
623|    for (rpos = 0; rpos < length; rpos++) {
624|      uc = buffer[rpos];
625|      if (uc == 0x000D && rpos < length-1 && buffer[rpos+1] == 0x000A) rpos++;
626|      if (uc == 0x000A || uc == 0x000D || uc == 0x0085 ||
627|          ((options & UTF8PROC_STRIPCC) && (uc == 0x000B || uc == 0x000C))) {
628|        if (options & UTF8PROC_NLF2LS) {
629|          if (options & UTF8PROC_NLF2PS) {
630|            buffer[wpos++] = 0x000A;
631|          } else {
632|            buffer[wpos++] = 0x2028;
633|          }
634|        } else {
635|          if (options & UTF8PROC_NLF2PS) {
636|            buffer[wpos++] = 0x2029;
637|          } else {
638|            buffer[wpos++] = 0x0020;
639|          }
640|        }
641|      } else if ((options & UTF8PROC_STRIPCC) &&
642|          (uc < 0x0020 || (uc >= 0x007F && uc < 0x00A0))) {
643|        if (uc == 0x0009) buffer[wpos++] = 0x0020;
644|      } else {
645|        buffer[wpos++] = uc;
646|      }
647|    }
648|    length = wpos;
649|  }
650|  if (options & UTF8PROC_COMPOSE) {
651|    utf8proc_int32_t *starter = NULL;
652|    const utf8proc_property_t *starter_property = NULL;
653|    utf8proc_propval_t max_combining_class = -1;
654|    utf8proc_ssize_t rpos;
655|    utf8proc_ssize_t wpos = 0;
656|    for (rpos = 0; rpos < length; rpos++) {
657|      utf8proc_int32_t current_char = buffer[rpos];
658|      if (current_char < 0 || current_char >= 0x110000) {
659|        /* skip grapheme-break sentinel or out-of-range codepoint;
660|           unsafe_get_property would OOB on utf8proc_stage1table (idx = uc >> 8) */
661|        continue;
662|      }
663|      const utf8proc_property_t *current_property = unsafe_get_property(current_char);
664|      if (starter && current_property->combining_class > max_combining_class) {
665|        /* combination perhaps possible */
666|        utf8proc_int32_t hangul_lindex;
667|        utf8proc_int32_t hangul_sindex;
668|        hangul_lindex = *starter - UTF8PROC_HANGUL_LBASE;
669|        if (hangul_lindex >= 0 && hangul_lindex < UTF8PROC_HANGUL_LCOUNT) {
670|          utf8proc_int32_t hangul_vindex;
671|          hangul_vindex = current_char - UTF8PROC_HANGUL_VBASE;
672|          if (hangul_vindex >= 0 && hangul_vindex < UTF8PROC_HANGUL_VCOUNT) {
673|            *starter = UTF8PROC_HANGUL_SBASE +
674|              (hangul_lindex * UTF8PROC_HANGUL_VCOUNT + hangul_vindex) *
675|              UTF8PROC_HANGUL_TCOUNT;
676|            starter_property = NULL;
677|            continue;
678|          }
679|        }
680|        hangul_sindex = *starter - UTF8PROC_HANGUL_SBASE;
681|        if (hangul_sindex >= 0 && hangul_sindex < UTF8PROC_HANGUL_SCOUNT &&
682|            (hangul_sindex % UTF8PROC_HANGUL_TCOUNT) == 0) {
683|          utf8proc_int32_t hangul_tindex;
684|          hangul_tindex = current_char - UTF8PROC_HANGUL_TBASE;
685|          if (hangul_tindex > 0 && hangul_tindex < UTF8PROC_HANGUL_TCOUNT) {
686|            *starter += hangul_tindex;
687|            starter_property = NULL;
688|            continue;
689|          }
690|        }
691|        if (!starter_property) {
692|          /* `*starter` is either a Hangul character, or points into
693|             the table `utf8proc_combinations_combined`. It is always
694|             valid. */
695|          starter_property = unsafe_get_property(*starter);
696|        }
697|        int idx = starter_property->comb_index;
698|        if (idx < 0x3FF && current_property->comb_issecond) {
699|          int len = starter_property->comb_length;
700|          utf8proc_int32_t max_second = utf8proc_combinations_second[idx + len - 1];
701|          if (current_char <= max_second) {
702|            int off;
703|            // TODO: binary search? arithmetic search?
704|            for (off = 0; off < len; ++off) {
705|              utf8proc_int32_t second = utf8proc_combinations_second[idx + off];
706|              if (current_char < second) {
707|                /* not found */
708|                break;
709|              }
710|              if (current_char == second) {
711|                /* found */
712|                utf8proc_int32_t composition = utf8proc_combinations_combined[idx + off];
713|                *starter = composition;
714|                starter_property = NULL;
715|                break;
716|              }
717|            }
718|            if (starter_property == NULL) {
719|              /* found */
720|              continue;
721|            }
722|          }
723|        }
724|      }
725|      buffer[wpos] = current_char;
726|      if (current_property->combining_class) {
727|        if (current_property->combining_class > max_combining_class) {
728|          max_combining_class = current_property->combining_class;
729|        }
730|      } else {
731|        starter = buffer + wpos;
732|        starter_property = NULL;
733|        max_combining_class = -1;
734|      }
735|      wpos++;
736|    }
737|    length = wpos;
738|  }
739|  return length;
