28|static void issue317(void) /* #317 */
29|{
30|    utf8proc_uint8_t input[] = {0xec, 0xa3, 0xa0, 0xe1, 0x86, 0xa7, 0x00}; /* "\uc8e0\u11a7" */
31|    utf8proc_uint8_t combined[] = {0xec, 0xa3, 0xa, 0x00}; /* "\uc8e1" */
32|    utf8proc_int32_t codepoint;
33|
34|    /* inputs that should *not* be combined* */
35|    check_compare("NFC", input, input, utf8proc_NFC(input), 1);
36|    utf8proc_encode_char(0x11c3, input+3);
37|    check_compare("NFC", input, input, utf8proc_NFC(input), 1);
38|
39|    /* inputs that *should* be combined (TCOUNT-1 chars starting at TBASE+1) */
40|    for (codepoint = 0x11a8; codepoint < 0x11c3; ++codepoint) {
41|        utf8proc_encode_char(codepoint, input+3);
42|        utf8proc_encode_char(0xc8e0 + (codepoint - 0x11a7), combined);
43|        check_compare("NFC", input, combined, utf8proc_NFC(input), 1);
44|    }
